    // set the upload file name
    $file_name = $uploaded_file_info['filename'] . '.' . $uploaded_file_info['extension'];
    $file_path = $file_upload_path . $file_name;

    // upload the file
    if (move_uploaded_file($_files['uploaded_file']['tmp_name'], $file_path)) {

        // create a thumbnail image of 100x100 pixels while maintaining aspect ratio
        $thumb_width = 100;
        $thumb_height = 100;

        // get the original image dimensions and type
        list($original_width, $original_height, $original_type) = getimagesize($file_path);

        // determine the original image type and create a new image resource from the file
        switch ($original_type) {
            case imagetype_jpeg:
                $original_image = imagecreatefromjpeg($file_path);
                break;
            case imagetype_png:
                $original_image = imagecreatefrompng($file_path);
                break;
            case imagetype_gif:
                $original_image = imagecreatefromgif($file_path);
                break;
        }

        // calculate the dimensions of the thumbnail image while maintaining aspect ratio
        $aspect_ratio = $original_width / $original_height;
        if ($thumb_width / $thumb_height > $aspect_ratio) {
            $thumb_width = $thumb_height * $aspect_ratio;
        } else {
            $thumb_height = $thumb_width / $aspect_ratio;
        }

        // create the thumbnail image resource and copy the original image to it
        $thumb_image = imagecreatetruecolor($thumb_width, $thumb_height);
        imagecopyresampled($thumb_image, $original_image, 0, 0, 0, 0, $thumb_width, $thumb_height, $original_width, $original_height);

        // save the thumbnail image as a file
        $thumb_path = $file_upload_path . 'thumb_' . $file_name;
        switch ($original_type) {
            case imagetype_jpeg:
                imagejpeg($thumb_image, $thumb_path, 90);
                break;
            case imagetype_png:
                imagepng($thumb_image, $thumb_path);
                break;
            case imagetype_gif:
                imagegif($thumb_image, $thumb_path);
                break;
        }

        // free the memory used by the image resources
        imagedestroy($original_image);
        imagedestroy($thumb_image);

        // display the thumbnail image
        echo '<img src="' . $thumb_path . '" alt="thumbnail image">';
    } else {
        echo 'there was an error uploading the file.';
    }
